def _handle_cross_references(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method == "POST":
        return _handle_cross_references_post(environ, raw_id, start_response)
    if method == "GET":
        return _handle_cross_references_get(environ, raw_id, start_response)
    return _error(
        start_response,
        "405 Method Not Allowed",
        "method_not_allowed",
        f"Method {method} is not allowed for this path.",
        allowed="GET, POST",
    )


def _handle_cross_reference_item(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    raw_item: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    """Delete one reference at ``/resources/{id}/cross-references/{repo}/{remote}``.

    The two item segments are percent-decoded as path segments and matched
    verbatim against the stored repository name and remote id. Only the
    reference record is removed: the resolved local resource and its
    dependency edge are retained and keep participating in the dependency
    and graph views.
    """

    if method != "DELETE":
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="DELETE",
        )

    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )

    # The item is exactly two path segments: repository then remote id.
    raw_repository, separator, raw_remote_id = raw_item.partition("/")
    repository, repository_error = _decode_reference_segment(
        raw_repository, "Repository"
    )
    if repository_error is not None:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            repository_error,
        )
    if not separator:
        # Only a repository segment was given: the remote id is missing.
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Remote id path segment must not be empty.",
        )
    remote_id, remote_id_error = _decode_reference_segment(
        raw_remote_id, "Remote id"
    )
    if remote_id_error is not None:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            remote_id_error,
        )

    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )
    # A declared non-empty (or malformed) body is a bad request; an omitted
    # Content-Length and an explicit zero length are accepted as empty.
    body_error = _bodyless_request_error(environ)
    if body_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", body_error
        )

    # The start resource is looked up before the reference, so a missing
    # start is reported as resource_not_found even when the reference is
    # absent as well.
    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    record = cross_reference_store.remove_one(
        store, raw_id, repository, remote_id
    )
    if record is None:
        # A reference that never existed and one already deleted answer
        # alike, so deleting is safe to repeat.
        return _error(
            start_response,
            "404 Not Found",
            "reference_not_found",
            "No cross-reference exists for that repository and remote id.",
        )

    return _json_response(
        start_response,
        "200 OK",
        record.to_dict(),
        trailing_newline=True,
    )


def _handle_cross_reference_summary(
    method: str,
    environ: dict[str, Any],
    start_response: StartResponse,
) -> Iterable[bytes]:
    """Global read-only summary of every cross-reference at ``GET /``.

    One record per registered reference in global registration order (the
    multiple references started by one resource keep their own order and
    the list is never reordered), each carrying the five per-resource
    listing fields plus ``local_id`` (the local resource the remote was
    resolved to) and ``edge_present`` (whether that dependency edge is
    still on the graph). Computed on the fly and recorded nowhere; no
    upstream is ever contacted.
    """

    if method != "GET":
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="GET",
        )

    # Read-only: a declared non-empty (or malformed) body is a bad request
    # without consulting any business data. An omitted header and an
    # explicit zero length are accepted as an empty body.
    body_error = _bodyless_request_error(environ)
    if body_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", body_error
        )

    # No parameters whatsoever are accepted.
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    records = [
        record.summary_dict(
            store.has_dependency(record.resource_id, record.local_id)
        )
        for record in cross_reference_store.list_all()
    ]
    return _json_response(
        start_response,
        "200 OK",
        records,
        trailing_newline=True,
    )


